template<class ForwardIterator>
ForwardIterator adjacent_find(ForwardIterator first, ForwardIterator last);

// Implementation notes:
// - This is a template function, so the compiler instantiates it for specific iterator types at compile time.
// - If a binary predicate is provided (e.g., via overload: template<class ForwardIterator, class BinaryPredicate> ForwardIterator adjacent_find(ForwardIterator first, ForwardIterator last, BinaryPredicate pred);), it replaces the default equality check, affecting how comparisons are generated in assembly (e.g., custom function calls instead of simple CMP instructions).
// - The function requires ForwardIterator, implying that the range can only be traversed once forward, which influences how the compiler handles aliasing and optimizations like loop unrolling.

code_example:
#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> vec = {1, 2, 2, 3, 4};  // Contiguous memory layout
    auto it = std::adjacent_find(vec.begin(), vec.end());  // Searches for adjacent equals
    if (it != vec.end()) {
        std::cout << "Found adjacent elements at position: " << std::distance(vec.begin(), it) << std::endl;  // Outputs the index of the first element in the pair
    } else {
        std::cout << "No adjacent elements found." << std::endl;
    }
    return 0;
}
